parameters.text:
=Candidate Name: {{ $json.Candidate_Name }} 
Candidate Email: {{ $json.Candidate_Email }}
Resume Text: {{ $json.resume_text }} Analyze this resume and determine the most suitable job roles for this candidate. Create a LinkedIn search query using 3 to 5 highly relevant job titles based strictly on the candidate's resume. Also identify the candidate's experience level, location if explicitly mentioned, and strongest skills. Return only valid JSON.

parameters.jsCode:
const input = $input.first().json;

const locations = input.locations || "";

const locationList = locations
  .split(",")
  .map(location => location.trim())
  .filter(location => location.length > 0);

return locationList.map(location => ({
  json: {
    ...input,
    jobLocation: location
  }
}));

const location = ($json.location || '').toLowerCase().trim();

let requestedCity = '';

if (location.includes(',')) {
  requestedCity = location.split(',')[0].trim();
} else {
  requestedCity = location;
}

return {
  json: {
    ...$json,
    requested_location_clean: location,
    requested_city: requestedCity
  }
};
